class PriceCache:
    def __init__(self, catalog):
        self.catalog = catalog
        self.cache = {}

    def price(self, sku, currency):
        if sku not in self.cache:
            self.cache[sku] = self.catalog[(sku, currency)]
        return self.cache[sku]

